#include <stdio.h>

int main(void)
{
    int value = 7;
    int *p = &value;
    *p = 12;
    printf("%d\n", value);
    return 0;
}

#include <stdio.h>

static void increment(int *p)
{
    (*p)++;
}

int main(void)
{
    int value = 5;
    increment(&value);
    printf("%d\n", value);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[] = {10, 20, 30};
    int *end = a + 3;
    printf("%d\n", *(end - 1));
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[] = {3, 6, 9};
    int *p = a;
    printf("%zu %d\n", sizeof a / sizeof a[0], p[1]);
    return 0;
}
